"""Generate the standalone build-along course from the tested source files.
Run from the repository: python3 tool/build_handbook.py
No third-party Python modules, network, or repository access needed by the reader.
"""
from pathlib import Path
import html
import json
import re

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT.parent / 'LuxeStays-Build-Handbook.html'
chapters = []
included = set()

def code(text, label='Terminal', path=None):
    attr = f' data-source="{html.escape(path)}"' if path else ''
    return f'<figure><figcaption>{html.escape(label)} <button type="button" class="copy">Copy</button></figcaption><pre><code{attr}>{html.escape(text)}</code></pre></figure>'

def source(path):
    included.add(path)
    text = (ROOT / path).read_text()
    comments = re.findall(r'^/// ?(.*)', text, re.M)
    intro = ' '.join(comments[:5]).strip()
    if not intro:
        intro = 'This file implements ' + Path(path).stem.replace('_', ' ') + '. Read the imports first to see which earlier pieces it connects.'
    classes = re.findall(r'^(?:abstract |final |sealed )*class (\w+)|^enum (\w+)', text, re.M)
    names = ', '.join(a or b for a,b in classes)
    return (f'<section class="lesson"><h3>Create or replace <code>{path}</code></h3>'
        f'<p>{html.escape(intro)}</p><p>Create its parent folders if necessary. The block is the complete file; replace the whole file rather than appending a second class.</p>'
        + (f'<p><strong>Reading guide:</strong> {html.escape(names)} are the named types introduced here. Constructor parameters supply their inputs; fields hold their values; methods perform the operations. Read one method at a time and follow the comments inside it.</p>' if names else '')
        + code(text, path + ' — complete file', path)
        + '<p class="tip">Save before continuing. If an import is red, check spelling and finish the files in this stage before running its checkpoint. Format after each file to catch missing brackets early.</p></section>')

def sources(paths):
    return ''.join(source(p) for p in paths)

def glob(pattern):
    return [str(p.relative_to(ROOT)) for p in sorted(ROOT.glob(pattern)) if str(p.relative_to(ROOT)) not in included]

def chapter(title, goal, concepts, body='', files=(), verify='fvm flutter analyze', checkpoint='', trouble='If analysis fails, read the first error, check its file path, and compare the complete block before continuing.'):
    n = len(chapters)+1
    text = f'<article id="stage-{n}"><p class="eyebrow">Stage {n:02d}</p><h2>{title}</h2><p class="objective"><strong>Objective:</strong> {goal}</p><p><strong>Prerequisite:</strong> '+ ('No previous Flutter knowledge. A computer with internet and enough space for the mobile SDKs.' if n==1 else f'Complete stage {n-1} and save its checkpoint.') + f'</p><h3>Understand before typing</h3>{concepts}{body}{sources(files)}<h3>Run and verify</h3>{code(verify)}<aside><strong>Troubleshooting.</strong> {trouble}</aside><p class="checkpoint"><strong>Checkpoint:</strong> {checkpoint or goal}</p><a href="#contents">Back to course map ↑</a></article>'
    chapters.append((title,text))

chapter('Meet LuxeStays', 'Understand the guest journey and the proof-of-concept boundary.',
    '<p>A guest searches a destination, selects dates and a room, adds it to a cart, enters guest details, authorizes a simulated payment and receives a reservation. Members can explore discounts and points. A mock server is a small program pretending to be remote services, so you can learn without paid accounts.</p><p>Flutter builds the screens. Dart is the programming language used for both app and mock. A WebView is an embedded browser for a hosted page. A repository combines data sources; a client sends HTTP requests to one service.</p>',
    '<div class="diagram">Guest → Flutter screen → state controller → repository → API client → local mock<br>Hosted payment page → bridge hint → server verification → reservation</div><aside>The shopping gateway is application-owned. Public SynXis Property Hub has a different retrieval API. We implement that subset separately and label all assumptions. This is not a production booking system.</aside>',
    verify='No command yet. Read the journey above.', checkpoint='You can explain which process draws the app and which serves the mock data.')
chapter('Install a reproducible toolchain', 'Prepare Flutter 3.47.4 / Dart 3.13.3 and a mobile emulator.',
    '<p>An SDK is a software development kit: compiler, libraries and command-line tools. Flutter includes Dart; do not install an unrelated Dart version. FVM is an optional SDK version manager used in this course to keep the project and CI on the same version.</p><ol><li>Follow <a href="https://docs.flutter.dev/install">Flutter installation</a> for your OS. Add Flutter to PATH so the terminal can find it.</li><li>Install Android Studio, its Android SDK and emulator, then create and boot a virtual phone. Accept the SDK licenses yourself with <code>flutter doctor --android-licenses</code>.</li><li>For iOS you need macOS and Xcode. Open Xcode once, install a simulator runtime and complete its first-launch setup. Install CocoaPods for this project’s plugin integration.</li><li>Install VS Code plus the Flutter extension (it includes Dart support). Open your project folder, not just a Dart file.</li></ol>',
    code('dart pub global activate fvm\nfvm install 3.47.4\nflutter doctor -v'),
    verify='flutter devices', checkpoint='A running Android emulator or iOS simulator is listed. Missing license/toolchain entries are resolved before mobile builds.', trouble='If fvm is not found, add your Dart pub-cache bin directory to PATH and reopen the terminal. Windows/Linux cannot build iOS. An SDK download may take several minutes.')
chapter('Create an empty project', 'Create generated platform hosts and run the counter app once.',
    '<p>The project folder contains <code>lib</code> for Dart source, <code>test</code> for tests, and <code>android</code>/<code>ios</code> for native hosts. <code>pubspec.yaml</code> lists packages. A package is a reusable library. The lockfile records exact resolved versions.</p>',
    code('mkdir luxe_course\ncd luxe_course\nfvm use 3.47.4 --force\nfvm flutter create --project-name luxe_stays --org com.luxestays --platforms android,ios,web .\nfvm flutter run'),
    verify='fvm flutter test', checkpoint='The generated counter app runs and its generated widget test passes. All later paths are relative to this new folder.', trouble='Do not create this practice folder inside the existing luxe_stays project. Use a separate workspace. Stop a running app with q in its terminal.')
chapter('Learn the Dart you need', 'Read values, classes, null safety and asynchronous code.',
    '<p><code>final</code> assigns a value once; <code>const</code> creates a compile-time constant. <code>String?</code> may hold text or null (no value). Use <code>??</code> for a default, and only use <code>!</code> when code has proved a value exists. A class groups values and behavior. An underscore makes a Dart member private to its library. In Dart 3.13 a named initializing parameter like <code>this._logger</code> has the public call-site name <code>logger:</code>; use the pinned SDK to support this syntax. Named parameters make calls readable. A List is an ordered collection; a Map associates keys with values.</p><p>A <code>Future&lt;T&gt;</code> promises one later result. <code>await</code> pauses that function without blocking the screen. A Stream delivers multiple events over time. <code>try/catch</code> handles exceptions. The app also uses Result values so expected failures can be displayed deliberately.</p>',
    code("Future<void> main() async {\n  const hotel = 'Luxe Paris';\n  final prices = <int>[32000, 32000, 38000, 0];\n  final total = prices.fold<int>(0, (sum, price) => sum + price);\n  await Future<void>.delayed(const Duration(milliseconds: 20));\n  print('$hotel: ${total / 100} USD before tax');\n}\n", 'Create tool/scratch.dart — temporary exercise'),
    verify='fvm dart run tool/scratch.dart', checkpoint='The terminal prints Luxe Paris: 1020.0 USD before tax. Delete tool/scratch.dart after this exercise.', trouble='Dollar interpolation belongs inside a Dart string. Amounts here are integer cents to avoid floating-point rounding in totals.')
chapter('Declare packages and lint rules', 'Install only the packages used by the app and server.',
    '<p>Riverpod stores state and supplies dependencies. Dio handles HTTP requests. webview_flutter embeds native browsers. cached_network_image caches images. flutter_secure_storage stores issued tokens. crypto supports PKCE challenges. Shelf and shelf_router run the local server. mocktail helps isolate code under test. Lints are static checks that catch common mistakes before running.</p><p>A caret allows compatible package releases; the lockfile pins one tested resolution. SDK packages have no independent version. Never copy real credentials into YAML.</p>',
    files=['pubspec.yaml','analysis_options.yaml','.fvmrc','.gitignore'], verify='fvm flutter pub get', checkpoint='Dependencies resolve. Keep the new pubspec.lock under source control. A reference lockfile is included in the final reproducibility appendix.', trouble='YAML uses spaces, not tabs. Dependencies and dev_dependencies are top-level sections. An incompatible SDK error means you are not using the pinned Flutter version.')
